import type { AlbumSlide } from "../types";

/**
 * Keeps both halves of a split greeting on the same open spread.
 *
 * With a cover in place the book shows page 0 alone and then pairs (1,2),
 * (3,4)… so a leaf at an odd index opens a spread and its neighbour closes it.
 * A greeting split into text-then-photo therefore lands on one spread only when
 * its text sits at an odd index; otherwise the reader meets the wish beside a
 * stranger's and has to turn the page to find its photo. Where the parity is
 * wrong, an empty leaf is slipped in ahead of the pair to correct it.
 *
 * Only worth doing while two leaves are actually visible — in single-page mode
 * the spacer would be a blank page the reader has to flip past — so callers
 * pass the plain slide list when the book is showing one page at a time.
 */
export function pairSplitGreetings(slides: AlbumSlide[]): AlbumSlide[] {
  const paired: AlbumSlide[] = [];

  for (const slide of slides) {
    const opensSplit = slide.kind === "page" && slide.part === "text";
    if (opensSplit && paired.length % 2 === 0) {
      paired.push({ kind: "blank", key: `${slide.key}-spacer` });
    }
    paired.push(slide);
  }

  return paired;
}
